codeExercises.solution:
import hashlib

def H(b: bytes) -> str:
    return hashlib.sha256(b).hexdigest()

def make_block(data: str, prev_hash: str) -> dict:
    return {"prev": prev_hash, "data": data}

def block_hash(block: dict) -> str:
    # si fa l'hash dell'intero blocco, incluso il suo hash pointer
    return H((block["prev"] + "|" + block["data"]).encode())

def build_chain(datas):
    chain, prev = [], "0" * 64
    for d in datas:
        b = make_block(d, prev)
        chain.append(b)
        prev = block_hash(b)
    return chain, prev          # prev = hash pointer di testa

def first_broken_link(chain, head):
    """Indice del primo blocco il cui hash non coincide con il puntatore successivo, o None."""
    for i in range(len(chain)):
        expected = chain[i + 1]["prev"] if i + 1 < len(chain) else head
        if block_hash(chain[i]) != expected:
            return i
    return None

chain, head = build_chain(["genesis", "Alice->Bob 5", "Bob->Carol 2", "Carol->Dave 1"])
print("testa:", head[:16])
print("catena integra, primo errore:", first_broken_link(chain, head))
chain[1]["data"] = "Alice->Bob 500"          # manomissione del blocco 1
print("dopo la manomissione, primo errore:", first_broken_link(chain, head))
# l'attaccante ricalcola tutti i puntatori successivi...
for i in range(2, len(chain)):
    chain[i]["prev"] = block_hash(chain[i - 1])
new_head = block_hash(chain[-1])
print("puntatori riparati, primo errore (testa fidata):", first_broken_link(chain, head))
print("la testa è cambiata:", new_head[:16], "!=", head[:16])

