codeExercises.solution:
import hashlib, math

class BloomFilter:
    def __init__(self, m: int, k: int):
        self.m, self.k = m, k
        self.bits = [0] * m

    def _positions(self, x: str):
        # h_i(x) = MD5(x || i) mod m, come suggerito nelle slide
        return [int(hashlib.md5(f"{x}|{i}".encode()).hexdigest(), 16) % self.m
                for i in range(self.k)]

    def add(self, x: str):
        for p in self._positions(x):
            self.bits[p] = 1

    def __contains__(self, x: str) -> bool:
        return all(self.bits[p] for p in self._positions(x))

m, n, k = 8000, 1000, 6            # 8 bit per elemento, k vicino all'ottimo
bf = BloomFilter(m, k)
for i in range(n):
    bf.add(f"addr-{i}")

assert all(f"addr-{i}" in bf for i in range(n))       # nessun falso negativo
trials = 100_000
fp = sum(f"other-{j}" in bf for j in range(trials))
print(f"bit a 1: {sum(bf.bits)}/{m} (atteso {m*(1-math.exp(-k*n/m)):.0f})")
print(f"falsi positivi empirici: {fp/trials:.4f}")
print(f"formula (1-e^(-kn/m))^k: {(1-math.exp(-k*n/m))**k:.4f}")

