codeExercises.solution:
import math

def p_fp(m_over_n: float, k: int) -> float:
    return (1 - math.exp(-k / m_over_n)) ** k

def best_int_k(m_over_n: float) -> int:
    return min(range(1, 60), key=lambda k: p_fp(m_over_n, k))

def bits_per_element(target_p: float) -> float:
    # con k ottimo: p = 2^-(m/n ln2)  =>  m/n = -ln p / (ln 2)^2
    return -math.log(target_p) / math.log(2) ** 2

print("m/n  k*=m/n*ln2  k_int  p_fp(k_int)")
for r in [2, 8, 10, 16, 24]:
    k = best_int_k(r)
    print(f"{r:3d}  {r*math.log(2):9.2f}  {k:5d}  {p_fp(r, k):.3g}")

print("m/n=10 al variare di k:", [round(p_fp(10, k), 4) for k in (5, 7, 10, 15)])
for p in (0.01, 0.001):
    r = bits_per_element(p)
    print(f"p={p}: {r:.2f} bit/elemento, k={round(r*math.log(2))}; "
          f"per 1 milione di elementi {r*1e6/8/1024:.0f} KiB")

