codeExercises.solution:
class Node:
    def __init__(self):
        self.children = {}      # etichetta dell'arco -> Node
        self.end = False        # marcatore di fine parola

def insert(root, word):
    node = root
    for ch in word:
        node = node.children.setdefault(ch, Node())
    node.end = True

def search(root, word):
    node = root
    for ch in word:
        if ch not in node.children:
            return False        # bloccati
        node = node.children[ch]
    return node.end             # nodo marcato?

def compress(node):
    """Patricia: fonde le catene di figli unici non marcati in un unico arco."""
    new_children = {}
    for label, child in node.children.items():
        while len(child.children) == 1 and not child.end:
            (l2, c2), = child.children.items()
            label, child = label + l2, c2
        compress(child)
        new_children[label] = child
    node.children = new_children

def count(node):
    return sum(1 + count(c) for c in node.children.values())

def edges(node, prefix=""):
    out = []
    for label, c in sorted(node.children.items()):
        out.append(f"{prefix}-{label}{'*' if c.end else ''}")
        out += edges(c, prefix + "  ")
    return out

root = Node()
for w in ["tree", "trie", "binary", "move", "movie", "bin"]:
    insert(root, w)
print("nodi trie:", count(root))
print("search tre:", search(root, "tre"), " search bin:", search(root, "bin"))
compress(root)
print("nodi Patricia:", count(root))
print("\n".join(edges(root)))

