# Nodi della MPT di slide 69, indicizzati dal loro hash (troncato, come in figura)
db = {
    "fa6dc296": ("ext",    "6",        "4221a50c"),
    "4221a50c": ("branch", {"4": "6d1c95b5", "8": "8cb162fc"}, None),
    "8cb162fc": ("leaf",   "6f727365", "stallion"),
    "6d1c95b5": ("ext",    "6f",       "99c9843b"),
    "99c9843b": ("branch", {"6": "b321240b"}, "verb"),
    "b321240b": ("ext",    "7",        "2123e223"),
    "2123e223": ("branch", {"6": "dbce88aa"}, "puppy"),
    "dbce88aa": ("leaf",   "5",        "coin"),
}

def to_nibbles(key: str) -> str:
    return key.encode().hex()           # "do" -> "646f"

def get(root: str, key: str, trace=None):
    nib, ref = to_nibbles(key), root
    while True:
        kind, a, b = db[ref]
        if trace is not None:
            trace.append(ref)
        if kind == "leaf":
            return b if nib == a else None
        if kind == "ext":
            if not nib.startswith(a):
                return None
            nib, ref = nib[len(a):], b
        else:                            # branch
            if nib == "":
                return b                 # la chiave finisce qui: campo Value
            if nib[0] not in a:
                return None
            nib, ref = nib[1:], a[nib[0]]

for k in ["do", "dog", "doge", "horse", "dot", "d"]:
    t = []
    print(f"{k:6s} {to_nibbles(k):10s} -> {get('fa6dc296', k, t)!s:9s} cammino: {' '.join(t)}")
